var c = Channel.CreateBounded<int>(4);
var prod = Task.Run(async () => { foreach (var n in new[] { 1, 2, 3 }) await c.Writer.WriteAsync(n); c.Writer.Complete(); });
var outC = Channel.CreateUnbounded<int>();
await Solution.PumpAsync(c.Reader, outC.Writer, 10, CancellationToken.None);
var got = new List<int>();
await foreach (var n in outC.Reader.ReadAllAsync()) got.Add(n);
Cj.Eq(string.Join(",", got), "10,20,30", "pumped and multiplied, sink completed");

var r = await Solution.RunBounded(100);
Cj.Eq(r.Count, 100, "all 100 items drained");
Cj.Eq(r[0], 0, "bounded channel keeps order"); Cj.Eq(r[99], 99, "in order");
